class Solution { fun minFlips(mat:Array<IntArray>):Int{val rows=mat.size;val columns=mat[0].size;val cells=rows*columns;var start=0;for(r in 0 until rows)for(c in 0 until columns)if(mat[r][c]==1)start=start or (1 shl (r*columns+c));val flips=IntArray(cells);val directions=arrayOf(intArrayOf(0,0),intArrayOf(1,0),intArrayOf(-1,0),intArrayOf(0,1),intArrayOf(0,-1));for(r in 0 until rows)for(c in 0 until columns)for(d in directions){val nr=r+d[0];val nc=c+d[1];if(nr in 0 until rows&&nc in 0 until columns)flips[r*columns+c]=flips[r*columns+c] xor (1 shl (nr*columns+nc))};val queue=java.util.ArrayDeque<IntArray>();val seen=BooleanArray(1 shl cells);queue.addLast(intArrayOf(start,0));seen[start]=true;while(queue.isNotEmpty()){val state=queue.removeFirst();if(state[0]==0)return state[1];for(flip in flips){val next=state[0] xor flip;if(!seen[next]){seen[next]=true;queue.addLast(intArrayOf(next,state[1]+1))}}};return -1} }
